SELECT

FROM sys_monthly_inspection_task t
LEFT JOIN sys_user cu ON t.create_user_id = cu.id AND cu.deleted = 0
WHERE t.deleted = 0

    AND t.status = #{status}


    AND (t.task_name LIKE CONCAT('%', #{taskName}, '%')
         OR t.task_no LIKE CONCAT('%', #{taskName}, '%'))


    AND t.inspection_start_time >= #{inspectionStartTime}


    AND t.inspection_end_time <= #{inspectionEndTime}

ORDER BY t.create_time DESC

SELECT
FROM sys_monthly_inspection_task t LEFT JOIN sys_user cu ON t.create_user_id = cu.id AND cu.deleted = 0 WHERE t.deleted = 0 AND t.create_user_id = #{userId}
AND t.status = #{status}
ORDER BY t.create_time DESC

SELECT d.dept_name as department_name, COUNT(t.id) as count FROM sys_monthly_inspection_task t LEFT JOIN sys_user u ON t.create_user_id = u.id AND u.deleted = 0 LEFT JOIN sys_dept d ON u.dept_id = d.id AND d.deleted = 0 WHERE t.deleted = 0
AND t.status = #{status}
GROUP BY u.dept_id, d.dept_name ORDER BY count DESC

